{"probes": [{"obligation_id": "OB-006", "strategy": "boundary", "rationale": "Falsifies the reading that only later ceilings clamp to cap by checking attempt 0 (unmodified base) equals cap when base > cap.", "code": "import pytest
from hypothesis import given, strategies as st, settings
import impl


@given(
    base=st.floats(min_value=1.0, max_value=1000.0, allow_nan=False, allow_infinity=False),
    extra=st.floats(min_value=0.0, max_value=1000.0, allow_nan=False, allow_infinity=False),
)
@settings(max_examples=100)
def test_ceiling_zero_equals_cap_when_cap_le_base(base, extra):
    cap = base - extra if base - extra > 0 else base
    # ensure cap <= base strictly by construction (cap = base - extra, extra >= 0)
    result = impl.schedule(1, base, cap, lambda u: u)
    assert result == [cap]
"}]}
